How can we retrieve information about highly reputable international organizations that advocate for gender parity and women's empowerment on a global scale and their successful initiatives?
[C++ code]
#include <iostream>
#include <fstream>
#include <string>
#include <vector>
using namespace std;
struct Organization {
    string name;
    string description;
    vector<string> initiatives;
};
int main() {
    vector<Organization> organizations;
    ifstream infile("organizations.txt");
    string line;
    while (getline(infile, line)) {
        Organization org;
        org.name = line;
        getline(infile, line);
        org.description = line;
        while (getline(infile, line) && line != "") {
            org.initiatives.push_back(line);
        }
        organizations.push_back(org);
    }
    // Now we have a vector of Organization structs with all the information we need
    // We can use this information to identify the organizations and their successful initiatives or programs launched aimed at furthering gender equality
    // For example:
    for (auto org : organizations) {
        if (org.name == "UN Women") {
            cout << "UN Women's successful initiative: " << org.initiatives[0] << endl;
        }
        else if (org.name == "Global Fund for Women") {
            cout << "Global Fund for Women's successful initiative: " << org.initiatives[0] << endl;
        }
        else if (org.name == "Plan International") {
            cout << "Plan International's successful initiative: " << org.initiatives[0] << endl;
        }
    }
    return 0;
}

